import urllib.request, re, urllib.parse, sys
query='Supply and Use Tables'
base='https://www.geostat.ge/en/search?search=' + urllib.parse.quote(query)

def get_page(page):
    url=base if page==1 else base+f'&page={page}'
    with urllib.request.urlopen(url, timeout=30) as resp:
        return resp.read().decode('utf-8','ignore')

pattern=r"<a href='([^']+)' class='item'>\s*<h3>([^<]+)</h3>\s*<p id='date'>([^<]+)</p>"

found=[]
for page in range(1, 50):
    html=get_page(page)
    items=re.findall(pattern, html)
    for link,title,date in items:
        t=title.lower()
        if 'supply' in t or 'use table' in t or 'supply and use' in t:
            found.append((page,link,title,date))
    if found:
        break
print('found', found[:5])
PY"}

